import { Link, useParams } from 'react-router-dom';
import { useState, useEffect } from 'react';
import { fetchProduct, fetchProducts, type Product } from '../lib/api';
import { createPublicUrl, createWhatsAppUrl } from '../lib/whatsapp';
import CatalogItem from '../components/CatalogItem';

function formatPrice(price: number): string {
  return price.toString().replace(/\B(?=(\d{3})+(?!\d))/g, '.');
}

export default function ProductPage() {
  const { id } = useParams<{ id: string }>();
  const [product, setProduct] = useState<Product | null>(null);
  const [related, setRelated] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeImage, setActiveImage] = useState(0);

  useEffect(() => {
    if (!id) return;
    setLoading(true);
    fetchProduct(id)
      .then(prod => {
        setProduct(prod);
        setActiveImage(0);
        // Fetch related: same category, exclude this product
        return fetchProducts();
      })
      .then(res => {
        const others = (res.data || []).filter(p => p.id !== id).slice(0, 4);
        setRelated(others);
      })
      .catch(() => {})
      .finally(() => setLoading(false));
  }, [id]);

  if (loading) {
    return (
      <main className="max-w-7xl mx-auto px-6 lg:px-8 py-12 lg:py-20">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-12 lg:gap-20 animate-pulse">
          <div className="lg:col-span-7 aspect-[3/4] bg-surface-container-low rounded-lg"></div>
          <div className="lg:col-span-5 space-y-6">
            <div className="h-6 w-1/3 bg-surface-container-low rounded"></div>
            <div className="h-12 w-2/3 bg-surface-container-low rounded"></div>
            <div className="h-32 bg-surface-container-low rounded-lg"></div>
          </div>
        </div>
      </main>
    );
  }

  if (!product) {
    return (
      <main className="max-w-7xl mx-auto px-6 py-20 text-center">
        <span className="material-symbols-outlined text-6xl text-outline mb-4 block">broken_image</span>
        <h1 className="font-headline text-3xl font-bold mb-2">Produk tidak ditemukan</h1>
        <Link to="/catalog" className="text-primary font-semibold hover:underline">← Kembali ke Katalog</Link>
      </main>
    );
  }

  const images = product.images || [];
  const displayImage = images[activeImage];
  const cond = product.condition;
  const productLink = createPublicUrl(`/product/${product.id}`);
  const productMessage = `Halo admin, saya tertarik dengan produk ${product.name} dengan harga Rp ${formatPrice(product.price)}.\nApakah masih tersedia? \nLink produk: ${productLink}`;

  return (
    <main className="max-w-7xl mx-auto px-6 lg:px-8 py-12 lg:py-20 animate-in fade-in duration-500 relative">
      <nav className="flex items-center gap-2 mb-10 text-xs font-label uppercase tracking-widest text-on-surface-variant flex-wrap">
        <Link to="/" className="hover:text-primary whitespace-nowrap transition-colors">Beranda</Link>
        <span className="material-symbols-outlined text-xs">chevron_right</span>
        <Link to="/catalog" className="hover:text-primary whitespace-nowrap transition-colors">Katalog</Link>
        <span className="material-symbols-outlined text-xs">chevron_right</span>
        <span className="text-on-surface whitespace-nowrap">{product.name}</span>
      </nav>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-12 lg:gap-20 items-start">
        {/* Gallery */}
        <div className="lg:col-span-7 flex flex-col gap-6">
          <div className="relative group aspect-[3/4] rounded-lg overflow-hidden bg-surface-container-low holographic-glow transition-all duration-500 lg:hover:scale-[1.02]">
            {displayImage ? (
              <img alt={product.name} className="w-full h-full object-cover" src={displayImage.url} />
            ) : (
              <div className="w-full h-full flex items-center justify-center">
                <span className="material-symbols-outlined text-7xl text-on-surface-variant/20">image</span>
              </div>
            )}
            {cond && (
              <div className="absolute top-6 right-6 bg-surface-bright/90 backdrop-blur-md px-4 py-2 rounded-full border border-[#4CAF50]/30 shadow-2xl">
                <span className="text-[#4CAF50] text-sm font-semibold flex items-center gap-2">
                  <span className="w-2 h-2 rounded-full bg-[#4CAF50] animate-pulse"></span>
                  {cond.name}
                </span>
              </div>
            )}
          </div>

          {/* Thumbnails */}
          {images.length > 0 && (
            <div className="grid grid-cols-4 gap-4">
              {images.map((img, i) => (
                <button
                  key={img.id}
                  onClick={() => setActiveImage(i)}
                  className={`aspect-square rounded-md overflow-hidden bg-surface-container-high transition-all ${i === activeImage ? 'ring-2 ring-primary opacity-100' : 'opacity-50 hover:opacity-100'}`}
                >
                  <img className="w-full h-full object-cover" src={img.url} alt={`thumbnail ${i + 1}`} />
                </button>
              ))}
            </div>
          )}
        </div>

        {/* Details */}
        <div className="lg:col-span-5 flex flex-col">
          <div className="mb-8">
            <span className="text-secondary font-label text-sm uppercase tracking-[0.2em] mb-3 block">
              {product.collection || product.categories?.map(c => c.name).join(' • ') || '—'}
            </span>
            <h1 className="text-4xl md:text-5xl font-extrabold font-headline leading-tight tracking-tight mb-4 text-white" style={{ textShadow: "0 2px 4px rgba(0,0,0,0.5)" }}>
              {product.name}
            </h1>
            <div className="flex flex-wrap items-center gap-4">
              {product.categories?.map(cat => (
                <span key={cat.id} className="bg-tertiary/10 text-tertiary text-xs font-bold px-3 py-1 rounded border border-tertiary/20 uppercase tracking-tighter">
                  {cat.name}
                </span>
              ))}
              <span className="text-on-surface-variant text-sm font-medium">
                {product.stock > 0 ? `✅ Stok: ${product.stock} tersedia` : '❌ Habis'}
              </span>
            </div>
          </div>

          <div className="p-6 md:p-8 rounded-lg bg-surface-container-low border border-outline-variant/10 mb-10">
            <div className="flex items-baseline gap-2 mb-6">
              <span className="text-on-surface-variant text-lg">Rp</span>
              <span className="text-4xl font-extrabold font-headline text-[#00D4FF]">{formatPrice(product.price)}</span>
            </div>
            <a
              className="w-full bg-gradient-to-r from-primary to-primary-container text-on-primary-container font-bold py-4 md:py-5 px-8 rounded-full flex items-center justify-center gap-3 hover:scale-[1.03] active:scale-[0.98] transition-all holographic-glow"
              href={createWhatsAppUrl(productMessage)}
              target="_blank"
              rel="noopener noreferrer"
            >
              <span className="material-symbols-outlined">chat</span>
              Beli via WhatsApp
            </a>
            <p className="mt-6 text-center text-xs text-on-surface-variant/60 font-medium leading-relaxed">
              Transaksi aman via Direct Admin atau Marketplace.
            </p>
          </div>

          <div className="space-y-8">
            {product.description && (
              <div className="border-t border-outline-variant/10 pt-8">
                <h3 className="font-headline text-lg font-bold mb-4 flex items-center gap-2">
                  <span className="material-symbols-outlined text-primary">description</span>
                  Deskripsi
                </h3>
                <p className="text-on-surface-variant leading-relaxed text-sm">{product.description}</p>
              </div>
            )}

            <div className="grid grid-cols-2 gap-6">
              {product.rarity && (
                <div className="flex flex-col gap-1">
                  <span className="text-on-surface-variant/50 text-xs font-label uppercase">Kelangkaan</span>
                  <span className="text-on-surface font-semibold">{product.rarity}</span>
                </div>
              )}
              {product.card_type && (
                <div className="flex flex-col gap-1">
                  <span className="text-on-surface-variant/50 text-xs font-label uppercase">Tipe</span>
                  <span className="text-on-surface font-semibold">{product.card_type}</span>
                </div>
              )}
              {product.graded_data && (
                <div className="flex flex-col gap-1">
                  <span className="text-on-surface-variant/50 text-xs font-label uppercase">Grade</span>
                  <span className="text-on-surface font-semibold">{product.graded_data}</span>
                </div>
              )}
              {cond && (
                <div className="flex flex-col gap-1">
                  <span className="text-on-surface-variant/50 text-xs font-label uppercase">Kondisi</span>
                  <span className="text-on-surface font-semibold">{cond.name}</span>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* Related Products */}
      {related.length > 0 && (
        <section className="mt-24 md:mt-32">
          <div className="flex justify-between items-end mb-10 md:mb-12">
            <div>
              <h2 className="text-2xl md:text-3xl font-extrabold font-headline mb-2">Produk Lainnya</h2>
              <p className="text-on-surface-variant text-sm md:text-base">Tambahkan koleksi lainnya ke pilihan Anda.</p>
            </div>
            <Link to="/catalog" className="text-primary font-semibold flex items-center gap-1 hover:gap-2 transition-all text-sm md:text-base whitespace-nowrap">
              Lihat Semua <span className="material-symbols-outlined">arrow_forward</span>
            </Link>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-8">
            {related.map(p => (
              <Link key={p.id} to={`/product/${p.id}`} className="block">
                <CatalogItem product={p} />
              </Link>
            ))}
          </div>
        </section>
      )}
    </main>
  );
}
